const ht = (en: string, es: string): HelpText => ({ en, es });
const def = (nameEn: string, nameEs: string, meaningEn: string, meaningEs: string): HelpDefinition => ({ name: ht(nameEn, nameEs), meaning: ht(meaningEn, meaningEs) });
const detail = (input: Partial<HelpManualDetail> & Pick<HelpManualDetail, "purpose" | "example">): HelpManualDetail => ({
  purpose: input.purpose,
  keyConcepts: input.keyConcepts ?? [], permissions: input.permissions ?? [], fields: input.fields ?? [], calculations: input.calculations ?? [],
  savedRecords: input.savedRecords ?? [], outputs: input.outputs ?? [], example: input.example,
});

