export function helpTopicForContext(context: string | null | undefined) {
  const topicId = HELP_CONTEXT_ALIASES[String(context ?? "")] ?? String(context ?? "");
  return HELP_TOPICS.find((topic) => topic.id === topicId) ?? HELP_TOPICS[0];
}
